def count_orbits(n):
    m=n//2
    total=0
    seen=set()
    for perm in itertools.permutations(range(1,n+1)):
        ok=True
        for i in range(n):
            if perm[i]+perm[(i+1)%n] != perm[(i+m)%n]+perm[(i+1+m)%n]:
                ok=False
                break
        if ok:
            # canonical rotation
            rots=[]
            for k in range(n):
                rots.append(tuple(perm[(i+k)%n] for i in range(n)))
            seen.add(min(rots))
    return len(seen)

