from fractions import Fraction

def cells_map(a, b, N=40):
    # positive distinct thresholds
    ths = sorted({t for t in (a, b, a+b, abs(a-b)) if t > 0})
    # cell index for integer w: 0..2m
    def cell(w):
        # count thresholds < w, and check equality
        for i,t in enumerate(ths):
            if w < t: return 2*i          # open interval before t
            if w == t: return 2*i+1       # the point t
        return 2*len(ths)                 # after last threshold
    return ths, [cell(w) for w in range(1, N+1)]

def max_n(a, b, N=60):
    ths, cs = cells_map(a, b, N)
    # largest n with 1..n all in distinct cells
    seen = {}
    n = 0
    for w, c in enumerate(cs, start=1):
        if c in seen:
            break
        seen[c] = w
        n = w
    return n, ths

best = 0
best_pairs = []
vals = [Fraction(i,2) for i in range(1, 41)]  # 0.5 .. 20 step 0.5
for a in vals:
    for b in vals:
        n, ths = max_n(a, b)
        if n > best:
            best, best_pairs = n, [(a,b,ths)]
        elif n == best:
            best_pairs.append((a,b,ths))
print("best n over grid:", best)
print("example pairs:", best_pairs[:5])
print("count of optimal pairs:", len(best_pairs))
